import re

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        if not isinstance(string, str) or not string:
            return "" if string == "" else string

        # Pattern for numeric character references: decimal or hex
        pattern = re.compile(r'&#(x[0-9A-Fa-f]+|\d+);')

        def repl(match):
            entity = match.group(1)
            try:
                if entity.startswith(('x', 'X')):
                    codepoint = int(entity[1:], 16)
                else:
                    codepoint = int(entity, 10)
                # Unicode range check
                if 0 <= codepoint <= 0x10FFFF:
                    return chr(codepoint)
            except Exception:
                pass
            # If not valid, return the original match
            return match.group(0)

        return pattern.sub(repl, string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        if not isinstance(char, str) or len(char) != 1:
            return False
        return char.lower() in '0123456789abcdef'

import PyPDF2
import os

class PDFHandler:
    """
    The class allows merging multiple PDF files into one and extracting text from PDFs using PyPDF2 library.
    """

    def __init__(self, filepaths):
        """
        takes a list of file paths filepaths as a parameter.
        It creates a list named readers using PyPDF2, where each reader opens a file from the given paths.
        """
        if filepaths is None:
            raise ValueError("filepaths cannot be None")
        if not isinstance(filepaths, list):
            raise TypeError("filepaths must be a list")
        self.filepaths = filepaths
        self.readers = []
        for fp in filepaths:
            if not isinstance(fp, str):
                raise TypeError("Each filepath must be a string")
            if not os.path.isfile(fp):
                raise FileNotFoundError(f"File not found: {fp}")
            try:
                reader = PyPDF2.PdfFileReader(fp)
                if reader.isEncrypted:
                    try:
                        reader.decrypt('')
                    except Exception:
                        raise ValueError(f"Cannot decrypt PDF: {fp}")
                self.readers.append(reader)
            except Exception as e:
                raise ValueError(f"Error opening PDF file {fp}: {e}")

    def merge_pdfs(self, output_filepath):
        """
        Read files in self.readers which stores handles to multiple PDF files.
        Merge them to one pdf and update the page number, then save in disk.
        :param output_filepath: str, ouput file path to save to
        :return: str, "Merged PDFs saved at {output_filepath}" if successfully merged
        >>> handler = PDFHandler(['a.pdf', 'b.pdf'])
        >>> handler.merge_pdfs('out.pdf')
        Merged PDFs saved at out.pdf
        """
        if not isinstance(output_filepath, str):
            raise TypeError("output_filepath must be a string")
        if not self.readers:
            raise ValueError("No PDF files to merge")
        merger = PyPDF2.PdfFileMerger()
        for fp in self.filepaths:
            merger.append(fp)
        try:
            with open(output_filepath, 'wb') as f_out:
                merger.write(f_out)
            return f"Merged PDFs saved at {output_filepath}"
        except Exception as e:
            raise IOError(f"Failed to write merged PDF: {e}")

    def extract_text_from_pdfs(self):
        """
        Extract text from pdf files in self.readers
        :return pdf_texts: list of str, each element is the text of one pdf file
        >>> handler = PDFHandler(['a.pdf', 'b.pdf'])
        >>> handler.extract_text_from_pdfs()
        ['Test a.pdf', 'Test b.pdf']
        """
        pdf_texts = []
        for reader in self.readers:
            text = ""
            for page_num in range(reader.numPages):
                try:
                    page = reader.getPage(page_num)
                    page_text = page.extract_text() if hasattr(page, 'extract_text') else page.extractText()
                    if page_text:
                        text += page_text
                except Exception:
                    continue
            pdf_texts.append(text)
        return pdf_texts

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements. 
    """

    @staticmethod
    def _format_value(value):
        if value is None:
            return "NULL"
        elif isinstance(value, str):
            return f"'{value}'"
        else:
            return f"'{value}'"

    @staticmethod
    def _format_where(where):
        if not where:
            return ""
        clauses = []
        for k, v in where.items():
            clauses.append(f"{k}={SQLQueryBuilder._format_value(v)}")
        return " WHERE " + " AND ".join(clauses)

    @staticmethod
    def select(table, columns='*', where=None):
        """
        Generate the SELECT SQL statement from the given parameters.
        :param table: str, the query table in database.
        :param columns: list of str, ['col1', 'col2'].
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        return query: str, the SQL query statement.
        >>> SQLQueryBuilder.select('table1', columns = ["col1","col2"], where = {"age": 15})
        "SELECT col1, col2 FROM table1 WHERE age='15'"
        """
        if isinstance(columns, list):
            columns_str = ", ".join(columns)
        elif columns == '*' or columns is None:
            columns_str = '*'
        else:
            columns_str = str(columns)
        query = f"SELECT {columns_str} FROM {table}"
        if where:
            query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def insert(table, data):
        """
        Generate the INSERT SQL statement from the given parameters.
        :param table: str, the table to be inserted in database.
        :param data: dict, the key and value in SQL insert statement
        :return query: str, the SQL insert statement.
        >>> SQLQueryBuilder.insert('table1', {'name': 'Test', 'age': 14})
        "INSERT INTO table1 (name, age) VALUES ('Test', '14')"
        """
        if not data or not isinstance(data, dict):
            raise ValueError("Data for insert must be a non-empty dict")
        keys = ", ".join(data.keys())
        values = ", ".join(SQLQueryBuilder._format_value(v) for v in data.values())
        query = f"INSERT INTO {table} ({keys}) VALUES ({values})"
        return query

    @staticmethod
    def delete(table, where=None):
        """
        Generate the DELETE SQL statement from the given parameters.
        :param table: str, the table that will be excuted with DELETE operation in database
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        :return query: str, the SQL delete statement.
        >>> SQLQueryBuilder.delete('table1', {'name': 'Test', 'age': 14})
        "DELETE FROM table1 WHERE name='Test' AND age='14'"
        """
        query = f"DELETE FROM {table}"
        if where:
            query += SQLQueryBuilder._format_where(where)
        return query

    @staticmethod
    def update(table, data, where=None):
        """
        Generate the UPDATE SQL statement from the given parameters.
        :param table: str, the table that will be excuted with UPDATE operation in database
        :param data: dict, the key and value in SQL update statement
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        >>> SQLQueryBuilder.update('table1', {'name': 'Test2', 'age': 15}, where = {'name':'Test'})
        "UPDATE table1 SET name='Test2', age='15' WHERE name='Test'"
        """
        if not data or not isinstance(data, dict):
            raise ValueError("Data for update must be a non-empty dict")
        set_clause = ", ".join(f"{k}={SQLQueryBuilder._format_value(v)}" for k, v in data.items())
        query = f"UPDATE {table} SET {set_clause}"
        if where:
            query += SQLQueryBuilder._format_where(where)
        return query
